pragma solidity =0.8.24;

import { Ownable2Step, Ownable } from '@openzeppelin/contracts/access/Ownable2Step.sol';
import { ReentrancyGuard } from '@openzeppelin/contracts/utils/ReentrancyGuard.sol';
import { SafeCast } from '@openzeppelin/contracts/utils/math/SafeCast.sol';
import { IERC20 } from '@openzeppelin/contracts/interfaces/IERC20.sol';
import { IERC721 } from '@openzeppelin/contracts/interfaces/IERC721.sol';
import { IERC4626 } from '@openzeppelin/contracts/interfaces/IERC4626.sol';
import { SafeERC20 } from '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';

import { IInternalAccountingUnit } from './InternalAccountingUnit.sol';
import { IVault } from './Vault.sol';
import { IwstETH } from './interfaces/lido/IwstETH.sol';
import { IRedemptionController } from './RedemptionController.sol';
import { IExemptionGate } from './periphery/NftExemptionGate.sol';
import { PathPausable } from './libs/PathPausable.sol';
import { OpsManaged } from './libs/OpsManaged.sol';
import { Rescuable } from './libs/Rescuable.sol';

interface IBlacklistable {
  function isBlacklisted(address _account) external view returns (bool);
}

interface ITreehouseRedemptionV3 {
  error MinimumNotMet();
  error RedemptionNotFound();
  error InWaitingPeriod();
  error InsufficientFundsInVault();
  error RedemptionError();
  error FeeExceeded();
  error ZeroAddress();
  error InvalidExemptionGate();
  error Blacklisted();
  error CollectionNotAccepted();

  event Redeemed(address indexed user, uint shares, uint assets);
  event RedeemedWithNft(address indexed user, address indexed collection, uint tokenId);
  event RedeemFinalized(address indexed user, uint assets, uint fee);
  event WaitingPeriodUpdated(uint32 latest, uint32 old);
  event MinRedeemUpdated(uint128 latest, uint128 old);
  event RedemptionFeeUpdated(uint32 latest, uint32 old);
  event TreasuryFeeUpdated(uint32 latest, uint32 old);
  event TreasuryUpdated(address latest, address old);
  event ExemptionGateUpdated(IExemptionGate latest, IExemptionGate old);
  event NftTreasuryUpdated(address latest, address old);

  struct RedemptionInfo {
    uint64 startTime;
    uint96 shares;
    uint128 assets;
    uint128 baseRate;
  }
}

/**
 * @notice Facilitate redemption of tAssets
 */
contract TreehouseRedemptionV3 is ITreehouseRedemptionV3, Ownable2Step, ReentrancyGuard, PathPausable, OpsManaged, Rescuable {
  using SafeERC20 for IERC20;
  using SafeCast for uint;
  uint32 internal constant PRECISION = 1e4;

  address public immutable IAU;
  address public immutable TASSET;
  IVault public immutable VAULT;
  IRedemptionController public immutable REDEMPTION_CONTROLLER;

  uint96 public minRedeemInUnderlying = 50 ether;
  uint32 public waitingPeriod = 7 days;
  uint96 public totalRedeemingShares;
  uint128 public totalRedeemingAssets;
  uint32 public redemptionFee;
  uint32 public treasuryFee = 1; // 1 bip to treasury by default
  address public treasury;
  IExemptionGate public exemptionGate; // address(0) = NFT exemption path disabled
  address public nftTreasury; // receives surrendered exemption tickets

  mapping(address => RedemptionInfo[]) private redemptionInfo;
  mapping(address => uint) public redeeming;

  constructor(
    address _creator,
    IVault _vault,
    IRedemptionController _redemptionController,
    address _treasury,
    IExemptionGate _exemptionGate,
    address _nftTreasury,
    address _ops,
    address _pauser
  ) Ownable(_creator) PathPausable(_pauser) OpsManaged(_ops) {
    if (_treasury == address(0)) revert ZeroAddress();
    if (_nftTreasury == address(0)) revert ZeroAddress();
    VAULT = _vault;
    TASSET = _vault.getTAsset();
    IAU = IERC4626(TASSET).asset();
    REDEMPTION_CONTROLLER = _redemptionController;
    treasury = _treasury;
    nftTreasury = _nftTreasury;
    _setExemptionGate(_exemptionGate);
  }

  modifier validateRedeem(address _userAddress, uint256 _index) {
    if (_index < redemptionInfo[_userAddress].length) {
      _;
    } else {
      revert RedemptionNotFound();
    }
  }

  /**
   * @notice Redeem tAsset
   * @param _shares amount of tAsset to redeem
   */
  function redeem(uint96 _shares) external nonReentrant whenNotPaused {
    uint128 _assets = IERC4626(TASSET).previewRedeem(_shares).toUint128();
    if (_assets < minRedeemInUnderlying) revert MinimumNotMet();

    _processRedeem(_shares, _assets);
  }

  /**
   * @notice Redeem tAsset below the minimum size by surrendering one NFT from an
   *         accepted collection to the NFT treasury
   * @dev The NFT is ALWAYS surrendered, even for redemptions at or above the minimum —
   *      callers above the floor should use redeem(). Each NFT is a single-use ticket.
   *      Requires prior ERC721 approval to THIS contract. The transfer goes straight from
   *      the caller to nftTreasury, so `from` can never be a parameter and this contract
   *      never custodies the NFT.
   *      NB: this path bypasses minRedeemInUnderlying, so an inflow cutoff via
   *      setMinRedeem(type(uint96).max) must be paired with setExemptionGate(address(0))
   * @param _shares amount of tAsset to redeem
   * @param _collection accepted ERC721 collection of the surrendered NFT
   * @param _tokenId NFT to surrender
   */
  function redeemWithNft(uint96 _shares, address _collection, uint _tokenId) external nonReentrant whenNotPaused {
    if (address(exemptionGate) == address(0)) revert ZeroAddress(); // feature disabled

    uint128 _assets = IERC4626(TASSET).previewRedeem(_shares).toUint128();
    // dust guard: never consume a ticket for a worthless entry
    if (_assets == 0) revert MinimumNotMet();

    if (!exemptionGate.isAcceptedCollection(_collection)) revert CollectionNotAccepted();

    IERC721(_collection).safeTransferFrom(msg.sender, nftTreasury, _tokenId);
    emit RedeemedWithNft(msg.sender, _collection, _tokenId);

    _processRedeem(_shares, _assets);
  }

  /**
   * @dev Common redemption tail: escrow the tAsset, record the entry, bump counters.
   *      Callers are responsible for entry gating (floor check or NFT ticket)
   */
  function _processRedeem(uint96 _shares, uint128 _assets) internal {
    IERC20(TASSET).safeTransferFrom(msg.sender, address(this), _shares);

    redemptionInfo[msg.sender].push(
      RedemptionInfo({
        startTime: block.timestamp.toUint64(),
        assets: _assets,
        shares: _shares,
        baseRate: _getBaseRate().toUint128()
      })
    );

    unchecked {
      redeeming[msg.sender] += _shares;
      totalRedeemingShares += _shares;
      totalRedeemingAssets += _assets;
    }

    emit Redeemed(msg.sender, _shares, _assets);
  }

  /**
   * @notice Finalize tAsset redemption
   * @param _redeemIndex index to finalize
   */
  function finalizeRedeem(
    uint _redeemIndex
  ) external nonReentrant whenNotPaused validateRedeem(msg.sender, _redeemIndex) {
    if (IBlacklistable(TASSET).isBlacklisted(msg.sender)) revert Blacklisted();

    RedemptionInfo storage _redeem = redemptionInfo[msg.sender][_redeemIndex];

    if (block.timestamp < _redeem.startTime + waitingPeriod) revert InWaitingPeriod();
    uint _assets = IERC4626(TASSET).redeem(_redeem.shares, address(this), address(this));
    redeeming[msg.sender] -= _redeem.shares;
    totalRedeemingShares -= _redeem.shares;
    totalRedeemingAssets -= _redeem.assets;

    address _underlying = VAULT.getUnderlying();

    uint _gross = _getReturnAmount(_redeem.assets, _redeem.baseRate, _assets, _getBaseRate());
    uint _holderFee = (_gross * redemptionFee) / PRECISION;
    uint _treasuryCut = (_gross * treasuryFee) / PRECISION;
    uint _returnAmount = _gross - _holderFee - _treasuryCut;

    if (_gross > _redeem.assets) revert RedemptionError();

    // amount actually leaving the vault: user payout + treasury cut (holderFee stays as donated IAU)
    uint _outflow = _returnAmount + _treasuryCut;
    if (IERC20(_underlying).balanceOf(address(VAULT)) < _outflow) revert InsufficientFundsInVault();

    IInternalAccountingUnit(IAU).burn(_outflow);
    REDEMPTION_CONTROLLER.redeem(_returnAmount, msg.sender);
    if (_treasuryCut > 0) {
      REDEMPTION_CONTROLLER.redeem(_treasuryCut, treasury);
    }

    // reused assignment - transfer leftover asset back into 4626 (holder fee + rate haircut)
    _assets = IERC20(IAU).balanceOf(address(this));

    if (_assets > 0) {
      IERC20(IAU).safeTransfer(TASSET, _assets);
    }

    // fee field is the user's total haircut (holder donation + treasury cut) — event shape
    // unchanged vs V2 for subscriber backwards compatibility
    emit RedeemFinalized(msg.sender, _returnAmount, _holderFee + _treasuryCut);

    // last because deletes are in-place
    _deleteRedeemEntry(_redeemIndex);
  }

  /**
   * @notice Set the waiting period for finalizing redeems
   * @param _newWaitingPeriod new waiting period in seconds
   */
  function setWaitingPeriod(uint32 _newWaitingPeriod) external onlyOwnerOrOps {
    emit WaitingPeriodUpdated(_newWaitingPeriod, waitingPeriod);
    waitingPeriod = _newWaitingPeriod;
  }

  /**
   * @notice Set the minimum redemption size
   * @dev must be the same amount of decimals as underlying
   * @param _minRedeemInUnderlying new minimum in IERC20(underlying).decimals()
   */
  function setMinRedeem(uint96 _minRedeemInUnderlying) external onlyOwnerOrOps {
    emit MinRedeemUpdated(_minRedeemInUnderlying, minRedeemInUnderlying);
    minRedeemInUnderlying = _minRedeemInUnderlying;
  }

  /**
   * @notice Set redemption fee (donated to remaining tAsset holders)
   * @dev capped so redemptionFee + treasuryFee can never exceed 100% (prevents
   *      underflow of the user payout in finalizeRedeem)
   * @param _newFee new redemption fee in bips
   */
  function setRedemptionFee(uint32 _newFee) external onlyOwnerOrOps {
    if (_newFee + treasuryFee > PRECISION) revert FeeExceeded();
    emit RedemptionFeeUpdated(_newFee, redemptionFee);
    redemptionFee = _newFee;
  }

  /**
   * @notice Set treasury fee (redeemed as underlying to `treasury`)
   * @dev capped so redemptionFee + treasuryFee can never exceed 100%
   * @param _newFee new treasury fee in bips
   */
  function setTreasuryFee(uint32 _newFee) external onlyOwnerOrOps {
    if (redemptionFee + _newFee > PRECISION) revert FeeExceeded();
    emit TreasuryFeeUpdated(_newFee, treasuryFee);
    treasuryFee = _newFee;
  }

  /**
   * @notice Set the treasury address
   * @param _newTreasury new treasury address
   */
  function setTreasury(address _newTreasury) external onlyOwner {
    if (_newTreasury == address(0)) revert ZeroAddress();
    emit TreasuryUpdated(_newTreasury, treasury);
    treasury = _newTreasury;
  }

  /**
   * @notice Set the treasury receiving surrendered exemption tickets
   * @dev owner only — deliberately NOT ops-settable. Prospective only: it cannot reach
   *      NFTs already surrendered, nor a user's standing approval. The treasury must never
   *      recirculate surrendered NFTs — every one returned to circulation is a fresh ticket
   * @param _newTreasury new NFT treasury address
   */
  function setNftTreasury(address _newTreasury) external onlyOwner {
    if (_newTreasury == address(0)) revert ZeroAddress();
    emit NftTreasuryUpdated(_newTreasury, nftTreasury);
    nftTreasury = _newTreasury;
  }

  /**
   * @notice Set the NFT exemption gate
   * @dev owner or ops. address(0) disables the NFT redemption path — ops-speed kill
   *      switch, so a full inflow cutoff (setMinRedeem(uint96.max) + setExemptionGate(0))
   *      fits in a single ops-timelock batch
   * @param _newGate new exemption gate
   */
  function setExemptionGate(IExemptionGate _newGate) external onlyOwnerOrOps {
    _setExemptionGate(_newGate);
  }

  /**
   * @dev A non-zero gate must have code. isAcceptedCollection returns a bool, so a
   *      codeless gate already fails closed (empty returndata fails to decode) — this
   *      surfaces the misconfiguration at set time instead of at the next redeemWithNft
   */
  function _setExemptionGate(IExemptionGate _newGate) internal {
    if (address(_newGate) != address(0) && address(_newGate).code.length == 0) revert InvalidExemptionGate();
    emit ExemptionGateUpdated(_newGate, exemptionGate);
    exemptionGate = _newGate;
  }

  /**
   * @notice Gets the redemption info of a user's redeem index
   * @param _user address of user
   * @param _redeemIndex user's redeem index
   */
  function getRedeemInfo(
    address _user,
    uint _redeemIndex
  ) external view validateRedeem(_user, _redeemIndex) returns (RedemptionInfo memory) {
    return redemptionInfo[_user][_redeemIndex];
  }

  /**
   * @notice Shares earmarked for the pending delayed book, for the atomic path's reservation
   */
  function totalRedeeming() external view returns (uint96) {
    uint _byAssets = IERC4626(TASSET).previewWithdraw(totalRedeemingAssets);
    if (_byAssets >= type(uint96).max) return type(uint96).max;
    uint96 _shares = totalRedeemingShares;
    return uint96(_byAssets) > _shares ? uint96(_byAssets) : _shares;
  }

  /**
   * @notice Gets the total number of redemptions in progress
   * @param _user address of user
   * @return number of in progress redemptions of user
   */
  function getRedeemLength(address _user) external view returns (uint256) {
    return redemptionInfo[_user].length;
  }

  /**
   * @notice Get all pending redemptions of user
   * @dev no guarantee of chronological ordering
   * @param _user address of user
   * @return array of in progress redemptions of user
   */
  function getPendingRedeems(address _user) external view returns (RedemptionInfo[] memory) {
    return redemptionInfo[_user];
  }

  /**
   * @notice Gas efficient way to delete a element in an array
   * @dev tradeoff - no guarantee of chronological ordering
   * @param index of redeem
   */
  function _deleteRedeemEntry(uint256 index) internal {
    redemptionInfo[msg.sender][index] = redemptionInfo[msg.sender][redemptionInfo[msg.sender].length - 1];
    redemptionInfo[msg.sender].pop();
  }

  /**
   * @notice Get the amount of asset/underlying to return before fees
   * @param _b0 redeemable assets at redeem
   * @param _c0 asset rate at redeem
   * @param _bn redeemable assets at finalize
   * @param _cn asset rate at finalize
   * @return return amount in underlying
   */
  function _getReturnAmount(uint128 _b0, uint128 _c0, uint _bn, uint _cn) internal pure returns (uint) {
    uint _minC;
    uint _maxC;

    if (_c0 > _cn) {
      _minC = _cn;
      _maxC = _c0;
    } else {
      _minC = _c0;
      _maxC = _cn;
    }

    return (_minC * (_b0 > _bn ? _bn : _b0)) / _maxC;
  }

  /**
   * @notice Get base rate of asset
   */
  function _getBaseRate() private view returns (uint) {
    return IwstETH(payable(VAULT.getUnderlying())).stEthPerToken();
  }

  ///////////////////////////////////////////// Overrides /////////////////////////////////////////////

  /**
   * @notice Global pause source is RedemptionController
   */
  function _globalPaused() internal view override returns (bool) {
    return REDEMPTION_CONTROLLER.paused();
  }

  ////////////////////// Inheritance overrides. Note: Sequence doesn't matter ////////////////////////

  function transferOwnership(address newOwner) public virtual override(Ownable2Step, Ownable) onlyOwner {
    super.transferOwnership(newOwner);
  }

  function _transferOwnership(address newOwner) internal virtual override(Ownable2Step, Ownable) {
    super._transferOwnership(newOwner);
  }
}

