import { Ownable2Step, Ownable } from '@openzeppelin/contracts/access/Ownable2Step.sol';
import { IERC721 } from '@openzeppelin/contracts/interfaces/IERC721.sol';
import { EnumerableSet } from '@openzeppelin/contracts/utils/structs/EnumerableSet.sol';

interface IExemptionGate {
  function isAcceptedCollection(address _collection) external view returns (bool);
}

/**
 * @notice NFT collection policy for the delayed redemption path's exemption tickets
 * @dev Policy only — this contract holds NO transfer authority and never moves a token.
 *      The redemption contract pulls the surrendered NFT itself, from msg.sender, so no
 *      caller can ever name a victim and users approve the redemption contract rather
 *      than this one. Surrendering one NFT from an accepted collection buys entry past
 *      the redemption contract's minimum-size floor for a single redemption; single-use
 *      is enforced by custody, since the NFT leaves the user.
 */
contract NftExemptionGate is IExemptionGate, Ownable2Step {
  using EnumerableSet for EnumerableSet.AddressSet;

  EnumerableSet.AddressSet private _acceptedCollections;

  error CollectionNotAccepted();
  error CollectionUpdateFailed();
  error ZeroAddress();

  event CollectionAdded(address indexed collection);
  event CollectionRemoved(address indexed collection);

  constructor(address _owner, address[] memory _initialCollections) Ownable(_owner) {
    uint _length = _initialCollections.length;
    for (uint i; i < _length; ++i) {
      _addCollection(_initialCollections[i]);
    }
  }

  /**
   * @notice Whether `_collection` is currently accepted as an exemption ticket
   * @param _collection ERC721 collection to check
   */
  function isAcceptedCollection(address _collection) external view returns (bool) {
    return _acceptedCollections.contains(_collection);
  }

  /**
   * @notice Accept an NFT collection as exemption tickets
   * @param _collection ERC721 collection to accept
   */
  function addCollection(address _collection) external onlyOwner {
    _addCollection(_collection);
  }

  /**
   * @dev Probes ERC165 support for the ERC721 interface before adding, so an EOA or a
   *      non-721 contract reverts here instead of surfacing later in redeemWithNft
   */
  function _addCollection(address _collection) internal {
    if (_collection == address(0)) revert ZeroAddress();
    if (!IERC721(_collection).supportsInterface(0x80ac58cd)) revert CollectionNotAccepted(); // ERC721 probe
    if (!_acceptedCollections.add(_collection)) revert CollectionUpdateFailed();
    emit CollectionAdded(_collection);
  }

  /**
   * @notice Stop accepting an NFT collection
   * @param _collection collection to remove
   */
  function removeCollection(address _collection) external onlyOwner {
    if (!_acceptedCollections.remove(_collection)) revert CollectionUpdateFailed();
    emit CollectionRemoved(_collection);
  }

  /**
   * @notice Get all accepted NFT collections
   */
  function getAcceptedCollections() external view returns (address[] memory) {
    return _acceptedCollections.values();
  }
}

