import { Ownable } from '@openzeppelin/contracts/access/Ownable.sol';
import { Pausable } from '@openzeppelin/contracts/utils/Pausable.sol';

/**
 * @notice Path-level pause combined with a global pause source. `paused()` is the union
 * of the local path pause and `_globalPaused()`, which the inheriting contract wires to
 * its global pause source
 * @dev Uses a plain bool instead of Pausable's _pause()/_unpause() so the path pause can
 * be toggled regardless of the global pause state (OZ's _pause is itself guarded by
 * whenNotPaused, which resolves through the overridden paused())
 */
abstract contract PathPausable is Pausable, Ownable {
  address public pauser;
  bool public pathPaused;

  error Unauthorized();

  event PathPauseSet(bool paused);
  event PauserUpdated(address latest, address old);

  /**
   * @param _pauser dedicated pauser (may be address(0) = no pauser; owner can always pause)
   */
  constructor(address _pauser) {
    pauser = _pauser;
    emit PauserUpdated(_pauser, address(0));
  }

  /**
   * @notice Set the path-level pause state of this contract
   * @dev owner or pauser. Does not affect the global pause source. Idempotent: a call
   *      that doesn't change state is a silent no-op, so PathPauseSet events map 1:1
   *      to actual state changes
   * @param _paused is contract paused
   */
  function setPathPause(bool _paused) external {
    if (msg.sender != owner() && msg.sender != pauser) revert Unauthorized();
    if (pathPaused == _paused) return;
    emit PathPauseSet(_paused);
    pathPaused = _paused;
  }

  /**
   * @notice Set a dedicated pauser for the contract
   * @dev address(0) revokes the pauser role
   * @param _pauser pauser address
   */
  function setPauser(address _pauser) external onlyOwner {
    emit PauserUpdated(_pauser, pauser);
    pauser = _pauser;
  }

  /**
   * @notice Paused if this path is paused or the global pause source is paused
   */
  function paused() public view virtual override returns (bool) {
    return pathPaused || _globalPaused();
  }

  /**
   * @dev Implement to wire in the global pause source
   */
  function _globalPaused() internal view virtual returns (bool);
}

