import { Ownable } from '@openzeppelin/contracts/access/Ownable.sol';

/**
 * @notice Ops-role management for routine parameter setters. `onlyOwnerOrOps` setters are
 * callable by the dedicated ops governor (intended: a short-delay ops timelock) OR the
 * owner (intended: the main long-delay timelock, kept as an escape hatch), mirroring the
 * owner-or-pauser pattern in PathPausable
 * @dev Rotating the ops governor is owner-only — a compromised ops role cannot hand
 * itself to an attacker. `address(0)` disables the role (owner-only mode)
 */
abstract contract OpsManaged is Ownable {
  address public ops;

  error NotOwnerOrOps();

  event OpsUpdated(address latest, address old);

  /**
   * @param _ops ops governor (may be address(0) = no ops role; owner can always call)
   */
  constructor(address _ops) {
    ops = _ops;
    emit OpsUpdated(_ops, address(0));
  }

  modifier onlyOwnerOrOps() {
    if (msg.sender != owner() && msg.sender != ops) revert NotOwnerOrOps();
    _;
  }

  /**
   * @notice Set the ops governor
   * @dev address(0) revokes the role
   * @param _ops new ops governor
   */
  function setOps(address _ops) external onlyOwner {
    emit OpsUpdated(_ops, ops);
    ops = _ops;
  }
}

