   * @dev Will revert blacklisted addresses
   */
  function _update(
    address from,
    address to,
    uint value
  ) internal virtual override notBlacklisted(from) notBlacklisted(to) notBlacklisted(msg.sender) {
    super._update(from, to, value);
  }

